const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Define geometry for Houston area
    const houston = ee.Geometry.Rectangle([-95.8, 29.6, -95.0, 30.2]); // Houston bounding box

    // 2. Define date ranges
    const april2024 = ee.DateRange('2024-04-01', '2024-04-30');
    const may18 = ee.DateRange('2024-05-18', '2024-05-19'); // Single day

    // 3. Get monthly composite for April 2024 (VIIRS DNB monthly)
    const aprilCollection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
        .filterBounds(houston)
        .filterDate(april2024);

    // 4. Get daily data for May 18, 2024 (VIIRS DNB daily)
    const mayCollection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VNP46A2')
        .filterBounds(houston)
        .filterDate(may18);

    // 5. Check if collections have data
    const aprilSize = aprilCollection.size().getInfo();
    const maySize = mayCollection.size().getInfo();

    console.log(`April 2024 Images: ${aprilSize}, May 18 Images: ${maySize}`);

    // Case C1: No images found
    if (aprilSize === 0 || maySize === 0) {
        // Try fallback: use daily data for April too if monthly is empty
        const aprilDaily = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VNP46A2')
            .filterBounds(houston)
            .filterDate('2024-04-01', '2024-05-01');

        const aprilDailySize = aprilDaily.size().getInfo();
        console.log(`April Daily Images: ${aprilDailySize}`);

        if (aprilSize === 0 && aprilDailySize === 0) {
            console.log("No data for April 2024.");
            console.log("<answer>C1</answer>");
            return;
        }
        if (maySize === 0) {
            console.log("No data for May 18, 2024.");
            console.log("<answer>C1</answer>");
            return;
        }

        // Use daily collection for April if monthly is empty
        const aprilImage = (aprilSize > 0) ? 
            aprilCollection.mean() : 
            aprilDaily.mean().clip(houston);
        const mayImage = mayCollection.mean().clip(houston);
    } else {
        const aprilImage = aprilCollection.mean().clip(houston);
        const mayImage = mayCollection.mean().clip(houston);
    }

    // 6. Process images - get average radiance
    const aprilRad = aprilImage.select('avg_rad');
    const mayRad = mayImage.select('avg_rad');

    // 7. Check pixel counts
    const aprilCount = aprilRad.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: houston,
        scale: 1000,
        maxPixels: 1e9
    }).get('avg_rad').getInfo();

    const mayCount = mayRad.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: houston,
        scale: 1000,
        maxPixels: 1e9
    }).get('avg_rad').getInfo();

    console.log(`April valid pixels: ${aprilCount}, May 18 valid pixels: ${mayCount}`);

    // Case C2: No valid pixels after processing
    if (aprilCount === 0 || mayCount === 0) {
        console.log("No valid pixels after processing.");
        console.log("<answer>C2</answer>");
        return;
    }

    // 8. Calculate mean brightness values
    const aprilMean = aprilRad.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: houston,
        scale: 1000,
        maxPixels: 1e9
    }).get('avg_rad').getInfo();

    const mayMean = mayRad.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: houston,
        scale: 1000,
        maxPixels: 1e9
    }).get('avg_rad').getInfo();

    console.log(`April mean radiance: ${aprilMean ? aprilMean.toFixed(4) : 'null'}`);
    console.log(`May 18 mean radiance: ${mayMean ? mayMean.toFixed(4) : 'null'}`);

    // 9. Validate results and determine answer
    // Check for invalid values (NaN, null, or unreasonable values - radiance should be positive)
    if (aprilMean === null || mayMean === null || 
        isNaN(aprilMean) || isNaN(mayMean) ||
        aprilMean < 0 || mayMean < 0) {
        console.log("Calculation produced invalid values.");
        console.log("<answer>C3</answer>");
        return;
    }

    // 10. Compare values - Did brightness decrease?
    const brightnessDecreased = mayMean < aprilMean;

    if (brightnessDecreased) {
        console.log("<answer>A</answer>");
    } else {
        console.log("<answer>B</answer>");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE();
